#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum MachineWordOperator {
    OperatorAnd,
    OperatorOr,
    OperatorXor,
    OperatorNot,
    OperatorShiftRight,
    OperatorShiftLeft,
    OperatorRotateRight,
    OperatorAddWrapping,
}

pub fn machine_word_operator_label(op: MachineWordOperator) -> String {
    match op.clone() {
    MachineWordOperator::OperatorAnd => "and".to_string(),
    MachineWordOperator::OperatorOr => "or".to_string(),
    MachineWordOperator::OperatorXor => "xor".to_string(),
    MachineWordOperator::OperatorNot => "not".to_string(),
    MachineWordOperator::OperatorShiftRight => "shift_right".to_string(),
    MachineWordOperator::OperatorShiftLeft => "shift_left".to_string(),
    MachineWordOperator::OperatorRotateRight => "rotate_right".to_string(),
    MachineWordOperator::OperatorAddWrapping => "add_wrapping".to_string(),
}
}

pub fn machine_word_operators() -> Rc<Vec<MachineWordOperator>> {
    thread_local! {
        static CACHED: Rc<Vec<MachineWordOperator>> = {
            Rc::new(vec![MachineWordOperator::OperatorAnd, MachineWordOperator::OperatorOr, MachineWordOperator::OperatorXor, MachineWordOperator::OperatorNot, MachineWordOperator::OperatorShiftRight, MachineWordOperator::OperatorShiftLeft, MachineWordOperator::OperatorRotateRight, MachineWordOperator::OperatorAddWrapping])
        };
    }
    CACHED.with(|c: &Rc<Vec<MachineWordOperator>>| c.clone())
}

pub fn machine_word_native_operate(op: String, bits: i64, a: i64, b: i64) -> i64 {
    v1_rt::machine_word_native_operate(&op, bits, a, b)
}

pub fn machine_word_apply(op: MachineWordOperator, width: WordWidth, a: i64, b: i64) -> i64 {
    v1_rt::machine_word_native_operate(&machine_word_operator_label(op), word_width_bits(width), a, b)
}

